templates.template:
/* =============================================================================
   WoW — a XenForo 2.3 port of the ProBoards "WowSkin" by Allan of Skins n Things.
   Black page in a gold frame, World of Warcraft banner, dark title bars with gold text,
   ornate gold caps above and below every block, a left-hand sidebar and WoW forum icons.
   The skin's images are embedded below, so the style needs no uploads.
   Banner and icon artwork © Blizzard Entertainment.
   ============================================================================= */

@wow-gold: #cba433;
@wow-gold-hover: #ecc95a;
@wow-text: #909090;
@wow-titlebg: linear-gradient(180deg, #202020 0%, #000 100%);

:root
{
	color-scheme: dark;
}

html,
body
{
	background: #000;
}

// ---- Gold frame around the whole forum ---------------------------------------------

.p-pageWrapper
{
	max-width: 990px;
	margin: 12px auto;
	background: #000;
	border: 1px solid #765a12;
	border-radius: 10px;
	box-shadow: 0 0 0 1px #af8f17, 0 0 0 2px #ddb21d;
}

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner
{
	max-width: 960px;
}

@media (max-width: 1010px)
{
	.p-pageWrapper
	{
		margin: 0;
		border-radius: 0;
		box-shadow: none;
		border-width: 0 0 1px;
	}
}

// ---- Header: the World of Warcraft banner -------------------------------------------
// Delete this section to use the logo set in Style properties instead.

.p-header
{
	background: transparent;
	border-radius: 10px 10px 0 0;
}

.p-header-content
{
	justify-content: center;
	padding: 12px 0 6px;
}

.p-header-logo
{
	margin: 0 auto;

	img
	{
		display: none;
	}

	a
	{
		display: block;
		width: 750px;
		max-width: 100%;
		margin: 0 auto;
		aspect-ratio: 750 / 200;
		background: url("data:image/jpeg;base64,") center / contain no-repeat;
		border: 3px solid #ddb21d;
		box-shadow: inset 0 0 0 1px #765a12;
	}
}

@media (max-width: @xf-responsiveNarrow)
{
	.p-header-logo a
	{
		width: calc(~'100vw - 20px');
	}
}

// ---- Navigation: dark bar with gold capitals -------------------------------------------

.p-nav
{
	background: @wow-titlebg;
	border-top: 1px solid #765a12;
	border-bottom: 1px solid #765a12;
	color: @wow-gold;
}

.p-nav-list
{
	justify-content: center;
	width: 100%;

	.p-navEl-link,
	.p-navEl-splitTrigger
	{
		color: @wow-gold;
		font-size: 11px;
		font-weight: 700;
		letter-spacing: 1.5px;
		text-transform: uppercase;

		&:hover
		{
			color: @wow-gold-hover;
			text-decoration: none;
		}
	}

	.p-navEl.is-selected
	{
		background: rgba(203, 164, 51, .14);
		box-shadow: inset 0 -2px 0 @wow-gold;

		.p-navEl-link
		{
			color: @wow-gold-hover;
		}
	}
}

.p-nav .p-navgroup
{
	background: transparent;
}

.p-nav .p-navgroup-link,
.p-nav-menuTrigger,
.p-nav-smallLogo
{
	color: @wow-gold;

	&:hover
	{
		background: rgba(203, 164, 51, .14);
		color: @wow-gold-hover;
		text-decoration: none;
	}
}

.p-sectionLinks
{
	background: #000;
	border-bottom: 1px solid #3a2d0b;

	a
	{
		color: @wow-gold;
	}
}

// ---- Body, with the sidebar on the left like the original side tables ------------------

.p-body,
.p-body-inner
{
	background: #000;
	color: @wow-text;
}

@media (min-width: (@xf-responsiveWide + 1))
{
	.p-body-main--withSidebar
	{
		.p-body-sidebar
		{
			order: -1;
			margin-left: 0;
			margin-right: 20px;
			padding-left: 0;
		}
	}
}

// Sidebar boxes: a single gold line, as in the original side tables
.p-body-sidebar .block-container
{
	border: 1px solid @wow-gold;
	border-radius: 0;

	&::before,
	&::after
	{
		content: none;
	}
}

.p-title-value
{
	color: @wow-gold;
}

// ---- Blocks: ornate gold cap above and below, gold side rails --------------------------

.block-container
{
	position: relative;
	background: #000;
	border: none;
	border-radius: 0;
	box-shadow: inset 2px 0 0 #6b4f11, inset -2px 0 0 #6b4f11;
	padding: 0 2px;

	&::before,
	&::after
	{
		content: '';
		display: block;
		height: 21px;
		margin: 0 -2px;
		background: url("data:image/png;base64,") center / 100% 100% no-repeat;
	}

	&::after
	{
		background-image: url("data:image/png;base64,");
	}
}

// Category and block titles: the skin's dark title gradient with gold text
.block-header,
.block-minorHeader,
.block-tabHeader,
.menu-header,
.menu-tabHeader,
.block-filterBar,
.dataList-row--header .dataList-cell
{
	background: @wow-titlebg;
	border-bottom: 1px solid #3a2d0b;
	color: @wow-gold;
	font-weight: 700;
	text-shadow: none;

	a,
	a:hover
	{
		color: @wow-gold;
	}

	.block-desc
	{
		color: @wow-text;
	}
}

.block-tabHeader .tabs-tab,
.menu-tabHeader .tabs-tab
{
	color: #8a7a4a;

	&:hover
	{
		color: @wow-gold-hover;
	}

	&.is-active
	{
		color: @wow-gold;
		border-color: @wow-gold;
	}
}

.block-footer
{
	background: @wow-titlebg;
	border-top-color: #3a2d0b;
	color: @wow-text;
}

// ---- Forum list ------------------------------------------------------------------

.node + .node
{
	border-top: 1px solid #1f1a0d;
}

.node-body
{
	background: #000;
}

.node-title a
{
	color: @wow-gold;
	font-weight: 700;

	&:hover
	{
		color: @wow-gold-hover;
	}
}

.node-description,
.node-meta,
.node-stats
{
	color: @wow-text;
}

.node-stats dt
{
	color: #8a7a4a;
}

// WoW logo icons: gold when there are new posts, grey when read.
.node--forum .node-icon i
{
	display: block;
	width: 44px;
	height: 44px;
	margin: 0 auto;
	background: url("data:image/png;base64,") center / 44px 44px no-repeat;
	border-radius: 50%;

	svg,
	&::before
	{
		display: none;
	}
}

.node--forum.node--unread .node-icon i
{
	background-image: url("data:image/png;base64,");
}

.node--link,
.node--page,
.node--category
{
	.node-icon i
	{
		color: @wow-gold;
	}
}

// ---- Thread lists and posts --------------------------------------------------------

.structItem
{
	background: #000;
	border-top-color: #1f1a0d;
}

.structItem-title a
{
	color: @wow-gold;

	&:hover
	{
		color: @wow-gold-hover;
	}
}

.structItem-minor,
.structItem-cell--meta,
.structItem-cell--latest
{
	color: @wow-text;
}

.message,
.message-inner
{
	background: #000;
	border-color: #3a2d0b;
}

.message-cell--user
{
	background: #0b0b0b;
	border-right-color: #3a2d0b;
}

.message-body
{
	color: #b4b4b4;
}

.message-userArrow::after
{
	border-right-color: #000;
}

.bbCodeBlock
{
	background: #0d0d0d;
	border-color: #3a2d0b;
}

// ---- Forms, menus and buttons ------------------------------------------------------

.input,
.button.button--link
{
	background: #0d0d0d;
	border-color: #5a4510;
	color: #c4c4c4;

	&:focus
	{
		border-color: @wow-gold;
	}
}

.menu-content,
.overlay
{
	background: #050505;
	border: 1px solid #5a4510;
	color: @wow-text;
}

.overlay-title
{
	background: @wow-titlebg;
	color: @wow-gold;
	border-bottom: 1px solid #5a4510;
}

.button,
a.button
{
	background: @wow-titlebg;
	border: 1px solid @wow-gold;
	color: @wow-gold;
	text-transform: uppercase;
	letter-spacing: 1px;
	font-size: 11px;

	&:hover
	{
		background: #1a1608;
		color: @wow-gold-hover;
		border-color: @wow-gold-hover;
	}
}

// ---- Footer, with the skin's credit image ---------------------------------------------

.p-footer
{
	background: @wow-titlebg;
	border-top: 1px solid #765a12;
	border-radius: 0 0 10px 10px;
	color: @wow-text;

	a
	{
		color: @wow-gold;

		&:hover
		{
			color: @wow-gold-hover;
		}
	}
}

.p-footer-copyright::after
{
	content: '';
	display: block;
	width: 400px;
	max-width: 100%;
	height: 20px;
	margin: 10px auto 0;
	background: url("data:image/png;base64,") center / contain no-repeat;
}
